function harvest(index){const p=S.plots[index];if(!isReady(p))return false;const c=cropDef(p.crop);S.stock[c.id]+=1+level('biggerBasket');p.crop=null;p.planted=0;p.ready=false;return true}
function sellAll(){let qty=0,earned=0;for(const c of CROPS){const n=S.stock[c.id]||0;qty+=n;earned+=n*c.sell}if(!qty){notify('Satılacak ürün yok — önce hasat zamanı!');return}earned=Math.floor(earned*multiplier());S.coins+=earned;S.totalEarned+=earned;S.sold+=qty;S.lifetime+=qty;S.stock=Object.fromEntries(CROPS.map(c=>[c.id,0]));notify(`🪙 ${qty} ürün ${format(earned)} ₺ karşılığında satıldı!`);render()}
function render(){const stockTotal=Object.values(S.stock).reduce((a,b)=>a+b,0),seedTotal=Object.values(S.seeds).reduce((a,b)=>a+b,0);$('coins').innerHTML=`${format(S.coins)} <span>₺</span>`;$('stock').innerHTML=`${format(stockTotal)} <span>ürün</span>`;$('sold').innerHTML=`${format(S.sold)} <span>ürün</span>`;$('prestigePoints').innerHTML=`${format(S.pp)} <span>PP</span>`;$('dayLabel').textContent=`☀️ ${format(S.day)}. Gün`;$('seedCount').textContent=`${format(seedTotal)} tohum`;$('plotCount').textContent=`${S.plots.length} tarla`;
const planted=S.plots.filter(p=>p.crop).length, ready=S.plots.filter(isReady).length;$('farmStatus').textContent=ready?`${ready} tarla hasada hazır!`:planted?`${planted} ekin güneşi bekliyor`:'Tohumlar seni bekliyor!';$('farmHint').textContent=ready?'Hasat et, ardından ambarını sat!':'Tarlana tohum ek, büyümelerini izle.';
$('plotVisuals').innerHTML=S.plots.map((p,i)=>`<div class="mini-plot ${p.crop?'':'locked'}" title="${p.crop?cropDef(p.crop).name+(isReady(p)?' — hasada hazır':' — büyüyor'):'Boş tarla'}"><span>${p.crop?(isReady(p)?'✨':cropDef(p.crop).icon):'·'}</span></div>`).join('');
let best=1,prog=0;S.plots.filter(p=>p.crop&&!isReady(p)).forEach(p=>{const duration=cropDef(p.crop).grow*growMultiplier();const x=Math.min(1,elapsed(p)/duration);if(x>prog){prog=x;best=duration-elapsed(p)}});$('farmProgress').style.width=`${ready?100:prog*100}%`;$('progressText').textContent=ready?'Hasada hazır':planted?`${Math.max(1,Math.ceil(best))} sn`:'Hazır';
$('plantAll').disabled=!S.plots.some(p=>!p.crop)&&!S.plots.some(p=>p.crop&&isReady(p));$('harvestAll').disabled=!ready;
renderCropPanel();renderShop();save()}
function renderCropPanel(){const c=$('cropContent');if(cropTab==='market'){c.innerHTML=`<div class="shop-grid">${CROPS.map(x=>{const open=unlocked(x),seedCost=Math.max(1,Math.floor(x.seedCost*(1-level('seedSaver')*.1)));return `<div class="shop-item"><div class="shop-item-top"><span class="shop-item-icon">${open?x.icon:'🔒'}</span><div><strong>${open?x.name:'Kilitli tohum'}</strong><small>${open?`Hasat ${x.grow} sn • Satış ${x.sell} ₺`:'Daha çok ürün sat'}</small></div></div><button class="btn ${S.coins>=seedCost?'btn-primary':'btn-soft'} buy-seed" data-id="${x.id}" ${!open||S.coins<seedCost?'disabled':''}>🌱 Tohum · ${format(seedCost)} ₺</button></div>`}).join('')}</div>`;c.querySelectorAll('.buy-seed').forEach(b=>b.onclick=()=>buySeed(b.dataset.id));return}
c.innerHTML=`<div class="crop-list">${CROPS.filter(x=>unlocked(x)).map(x=>`<div class="crop-row"><div class="crop-icon">${x.icon}</div><div class="crop-info"><strong>${x.name}</strong><small>${format(S.seeds[x.id])} tohum · ${x.grow} sn büyüme · ${x.sell} ₺/adet</small></div><div class="crop-action"><button class="btn ${S.seeds[x.id]?'btn-primary':'btn-soft'} plant-one" data-id="${x.id}" ${S.seeds[x.id]?'':'disabled'}>Ekim yap</button></div></div>`).join('')}<button class="btn btn-gold" id="sellButton" style="width:100%;margin-top:3px">🧺 Ürünleri sat · ${format(Object.values(S.stock).reduce((a,b)=>a+b,0))} adet</button></div>`;
c.querySelector('#sellButton').onclick=sellAll;c.querySelectorAll('.plant-one').forEach(b=>b.onclick=()=>{const p=S.plots.find(p=>!p.crop);if(!p){notify('Boş tarla yok — dükkândan yeni tarla al!');return}plant(p,cropDef(b.dataset.id));render()})}
function buySeed(id){const x=cropDef(id),price=Math.max(1,Math.floor(x.seedCost*(1-level('seedSaver')*.1)));if(S.coins<price||!unlocked(x))return;S.coins-=price;S.seeds[id]++;notify(`${x.icon} ${x.name} tohumu alındı!`);render()}
function renderShop(){const el=$('shopContent');el.innerHTML=UPGRADES.map(u=>{const lv=level(u.id),price=cost(u),max=lv>=u.max;return `<div class="upgrade-row"><div class="upgrade-icon">${u.icon}</div><div class="upgrade-info"><strong>${u.name} <span style="color:#88927e;font-weight:700">${lv}/${u.max}</span></strong><small>${u.desc}</small></div><button class="btn ${S.coins>=price&&!max?'btn-primary':'btn-soft'} upgrade-buy" data-id="${u.id}" ${S.coins<price||max?'disabled':''}>${max?'MAX':`₺ ${format(price)}`}</button></div>`}).join('')+`<div class="upgrade-foot" style="margin-top:10px">🧺 Ambarında ${format(Object.values(S.stock).reduce((a,b)=>a+b,0))} ürün var. Ürünlerini satıp geliştirmelerini finanse et.</div>`;el.querySelectorAll('.upgrade-buy').forEach(b=>b.onclick=()=>buyUpgrade(b.dataset.id))}
function buyUpgrade(id){const u=UPGRADES.find(x=>x.id===id),price=cost(u);if(level(id)>=u.max||S.coins<price)return;S.coins-=price;S.upgrades[id]=level(id)+1;if(id==='extraPlot')S.plots.push({crop:null,planted:0,ready:false});notify(`${u.icon} ${u.name} geliştirildi!`);render()}
function openModal(title,html){$('modalTitle').textContent=title;$('modalBody').innerHTML=html;$('modal').classList.add('open')}
function openTree(){openModal('🌿 Yetenek ağacı',`<p class="modal-intro">Bu dalları satışlardan kazandığın <b>₺</b> ile geliştir. Yeteneklerin prestij sıfırlamasından sonra da kalır.</p><div class="tree-grid">${UPGRADES.map(u=>{const lv=level(u.id),price=cost(u);return `<div class="tree-node ${lv?'unlocked':''}"><div class="node-top"><span class="node-icon">${u.icon}</span><div><div class="node-title">${u.name}</div><div class="node-level">SEVİYE ${lv} / ${u.max}</div></div></div><p>${u.desc}</p><button class="btn ${S.coins>=price&&lv<u.max?'btn-primary':'btn-soft'} tree-buy" data-id="${u.id}" ${S.coins<price||lv>=u.max?'disabled':''}>${lv>=u.max?'Tamamlandı':`Geliştir · ${format(price)} ₺`}</button></div>`}).join('')}</div>`);$('modalBody').querySelectorAll('.tree-buy').forEach(b=>b.onclick=()=>{buyUpgrade(b.dataset.id);openTree()})}
function potentialPP(){return Math.floor(Math.sqrt(Math.max(0,S.totalEarned)/1800))}
function openPrestige(){const gain=potentialPP();openModal('✨ Prestij bahçesi',`<div class="prestige-banner"><div><strong>Yeni bir döngü, daha büyük bir çiftlik.</strong><small>Sıfırlama sonrası bu kalıcı yetenekler seninle kalır.</small></div><span style="font-size:28px">🌙</span></div><p class="modal-intro">Prestij yaptığında paraların, tohumların, ürünlerin ve çiftlik geliştirmelerin sıfırlanır. Karşılığında kazandığın PP ve prestij ağacı kalıcıdır. <b>Ömür boyu kazancın: ${format(S.totalEarned)} ₺</b></p><div class="prestige-banner"><div><strong>Bu sıfırlamada kazanacağın</strong><small>Ömür boyu kazanç arttıkça daha çok PP kazanırsın.</small></div><b style="font-size:20px;color:#f3ca69">+${gain} PP</b></div><div class="tree-grid">${PERKS.map(p=>{const lv=perkLevel(p.id),can=S.pp>=p.cost&&lv<p.max;return `<div class="tree-node ${lv?'unlocked':''}"><div class="node-top"><span class="node-icon">${p.icon}</span><div><div class="node-title">${p.name}</div><div class="node-level">SEVİYE ${lv} / ${p.max}</div></div></div><p>${p.desc}</p><button class="btn ${can?'btn-primary':'btn-soft'} perk-buy" data-id="${p.id}" ${can?'':'disabled'}>${lv>=p.max?'Tamamlandı':`Yükselt · ${p.cost} PP`}</button></div>`}).join('')}</div><div class="reset-box"><strong>⚠ Çiftliği yeni baştan kur</strong><p>Prestij puanı almak için en az 1 PP kazanmış olmalısın. Sıfırlama: ₺, tohumlar, ürünler, satış sayacı, normal yetenekler ve tarlalar. Kalır: toplam kazanç, PP ve prestij yetenekleri.</p><button class="btn" id="resetFarm" ${gain<1?'disabled':''}>${gain<1?'En az 1 PP için daha çok kazan':`Sıfırla ve ${gain} PP kazan`}</button></div>`);$('modalBody').querySelectorAll('.perk-buy').forEach(b=>b.onclick=()=>buyPerk(b.dataset.id));const reset=$('resetFarm');if(reset)reset.onclick=prestigeReset}
function buyPerk(id){const p=PERKS.find(x=>x.id===id);if(S.pp<p.cost||perkLevel(id)>=p.max)return;S.pp-=p.cost;S.perks[id]=perkLevel(id)+1;notify(`${p.icon} ${p.name} kalıcı olarak açıldı!`);render();openPrestige()}
function prestigeReset(){const gain=potentialPP();if(gain<1)return;if(!confirm(`Çiftliğini sıfırlayıp ${gain} PP kazanmak istediğine emin misin?`))return;S.pp+=gain;const earned=S.totalEarned,day=S.day,perks={...S.perks};S={...initial(),pp:S.pp,totalEarned:earned,day,perks};S.seeds.carrot+=perkLevel('seedling')*3;save();render();$('modal').classList.remove('open');notify(`✨ Çiftlik yenilendi! +${gain} prestij puanı`)}
